import * as Phaser from "phaser";
import { HEADING_COUNT, insideIsland, ISLAND_THEMES, SIGHT_RADIUS_TILES, Terrain, terrainAt, type IslandTheme } from "@pirate-sea-race/content";
import { defaultSimulationConfig } from "@pirate-sea-race/simulation";
import { followScroll, TILE_PIXELS, VIEW_HEIGHT, VIEW_WIDTH } from "./camera.js";
import { FogOfWar } from "./fog.js";
import { cssColor, slotColor, type MatchView } from "./matchView.js";

const { map } = defaultSimulationConfig;
const WORLD_WIDTH = map.widthTiles * TILE_PIXELS;
const WORLD_HEIGHT = map.heightTiles * TILE_PIXELS;
const PIXELS_PER_SUB_UNIT = TILE_PIXELS / map.subUnitsPerTile;

/** Placeholder palette. None of these is near a ship colour, so a ship's colour on the canvas is always a ship. */
const SEA_COLOR = 0x0b3d5c;
const GRID_COLOR = 0x145374;
const SHOAL_COLOR = 0x2e7d86;
const SHOAL_FLECK = 0x4f9aa0;
const DOCK_COLOR = 0x8b5a2b;
const DOCK_PLANK = 0x6b4220;
const LAND_COLORS: Readonly<Record<IslandTheme, number>> = { tropical: 0x6b8e23, volcanic: 0x5b4a45, ruin: 0x9a8f73, mist: 0x7d8a99 };
const FOG_COLOR = 0x16202a;
const OWN_RING_COLOR = 0xfff3b0;
const SIGHT_COLOR = 0x9bd1e5;

/** Tile indexes in the generated tileset texture. */
const TILE_SEA = 0;
const TILE_SHOAL = 1;
const TILE_DOCK = 2;
const TILE_LAND = 3;

const MINIMAP_SCALE = 0.75;
const MINIMAP_MARGIN = 8;

/** A ship as drawn this frame, in canvas pixels, for the DOM report tests read. */
export interface DrawnShip {
  readonly id: string;
  readonly x: number;
  readonly y: number;
  readonly color: string;
}

function landTile(tileX: number, tileY: number): number {
  const theme = map.islands.find((island) => insideIsland(island, tileX, tileY))?.theme ?? "tropical";
  return TILE_LAND + ISLAND_THEMES.indexOf(theme);
}

function tileIndex(tileX: number, tileY: number): number {
  switch (terrainAt(map, tileX, tileY)) {
    case Terrain.Land:
      return landTile(tileX, tileY);
    case Terrain.Shoal:
      return TILE_SHOAL;
    case Terrain.Dock:
      return TILE_DOCK;
    default:
      return TILE_SEA;
  }
}

function tileColor(tileX: number, tileY: number): number {
  const index = tileIndex(tileX, tileY);
  if (index >= TILE_LAND) return LAND_COLORS[ISLAND_THEMES[index - TILE_LAND]!];
  return [SEA_COLOR, SHOAL_COLOR, DOCK_COLOR][index]!;
}

/**
 * Draws the sea: the tile map from content, the ships the server sent at interpolated positions, a camera that
 * follows the player's ship, the sight circle, and a minimap whose fog clears along the player's path. Each frame
 * it records what it drew in data attributes on the report element (`data-drawn-ships`, `data-camera`,
 * `data-fog-revealed`) for the browser tests.
 */
export class SeaScene extends Phaser.Scene {
  private readonly shipGraphics = new Map<string, Phaser.GameObjects.Graphics>();
  private readonly fog = new FogOfWar(map.widthTiles, map.heightTiles, SIGHT_RADIUS_TILES);
  private minimap!: Phaser.Textures.CanvasTexture;
  private minimapMarks!: Phaser.GameObjects.Graphics;
  private sight!: Phaser.GameObjects.Graphics;
  private lastReport = "";

  constructor(
    private readonly view: MatchView,
    private readonly report: HTMLElement,
  ) {
    super("sea");
  }

  create(): void {
    this.createTerrain();
    this.sight = this.add.graphics();
    this.sight.lineStyle(1, SIGHT_COLOR, 0.45);
    this.sight.strokeCircle(0, 0, SIGHT_RADIUS_TILES * TILE_PIXELS);
    this.sight.setDepth(1);
    this.createMinimap();
  }

  /** The tile map, as a Phaser tilemap over a tileset texture drawn here in placeholder colours. */
  private createTerrain(): void {
    const kinds = TILE_LAND + ISLAND_THEMES.length;
    const tileset = this.textures.createCanvas("terrain-tiles", kinds * TILE_PIXELS, TILE_PIXELS)!;
    const context = tileset.getContext();
    const paint = (index: number, color: number) => {
      context.fillStyle = cssColor(color);
      context.fillRect(index * TILE_PIXELS, 0, TILE_PIXELS, TILE_PIXELS);
    };
    paint(TILE_SEA, SEA_COLOR);
    paint(TILE_SHOAL, SHOAL_COLOR);
    context.fillStyle = cssColor(SHOAL_FLECK);
    for (const [x, y] of [[3, 4], [10, 2], [6, 10], [13, 12], [2, 13]] as const) context.fillRect(TILE_SHOAL * TILE_PIXELS + x, y, 2, 2);
    paint(TILE_DOCK, DOCK_COLOR);
    context.fillStyle = cssColor(DOCK_PLANK);
    for (const y of [4, 9, 14]) context.fillRect(TILE_DOCK * TILE_PIXELS, y, TILE_PIXELS, 1);
    ISLAND_THEMES.forEach((theme, index) => paint(TILE_LAND + index, LAND_COLORS[theme]));
    tileset.refresh();

    // Open sea is left empty (-1): the camera's background is the sea, so the layer draws only the few land, shoal
    // and dock tiles in view. Drawing every sea tile too costs a software renderer most of its frame rate.
    const data = Array.from({ length: map.heightTiles }, (_, tileY) =>
      Array.from({ length: map.widthTiles }, (_, tileX) => {
        const index = tileIndex(tileX, tileY);
        return index === TILE_SEA ? -1 : index;
      }),
    );
    const tilemap = this.make.tilemap({ data, tileWidth: TILE_PIXELS, tileHeight: TILE_PIXELS });
    const tiles = tilemap.addTilesetImage("terrain", "terrain-tiles", TILE_PIXELS, TILE_PIXELS, 0, 0)!;
    tilemap.createLayer(0, tiles, 0, 0);

    // A chart grid every eight tiles, so open water shows the ship's motion.
    const grid = this.add.graphics();
    grid.lineStyle(1, GRID_COLOR, 0.6);
    for (let tile = 0; tile <= map.widthTiles; tile += 8) grid.lineBetween(tile * TILE_PIXELS, 0, tile * TILE_PIXELS, WORLD_HEIGHT);
    for (let tile = 0; tile <= map.heightTiles; tile += 8) grid.lineBetween(0, tile * TILE_PIXELS, WORLD_WIDTH, tile * TILE_PIXELS);

    for (const island of map.islands) {
      const label = this.add.text((island.tileX + island.widthTiles / 2) * TILE_PIXELS, (island.tileY - 1.2) * TILE_PIXELS, island.name, {
        fontFamily: "system-ui, sans-serif",
        fontSize: "12px",
        color: "#e8f1f5",
      });
      label.setOrigin(0.5, 0.5).setAlpha(0.85);
    }
  }

  /** The minimap: one pixel per tile, fogged until the player's ship has seen it. */
  private createMinimap(): void {
    this.minimap = this.textures.createCanvas("minimap", map.widthTiles, map.heightTiles)!;
    const context = this.minimap.getContext();
    context.fillStyle = cssColor(FOG_COLOR);
    context.fillRect(0, 0, map.widthTiles, map.heightTiles);
    this.minimap.refresh();
    const left = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
    const frame = this.add.graphics().setScrollFactor(0).setDepth(10);
    frame.lineStyle(2, 0x9bb8c6, 0.9);
    frame.strokeRect(left - 1, MINIMAP_MARGIN - 1, map.widthTiles * MINIMAP_SCALE + 2, map.heightTiles * MINIMAP_SCALE + 2);
    this.add.image(left, MINIMAP_MARGIN, "minimap").setOrigin(0, 0).setScale(MINIMAP_SCALE).setScrollFactor(0).setDepth(10);
    this.minimapMarks = this.add.graphics().setScrollFactor(0).setDepth(11);
  }

  private revealFog(x: number, y: number): void {
    const fresh = this.fog.revealAround(Math.floor(x / TILE_PIXELS), Math.floor(y / TILE_PIXELS));
    if (fresh.length === 0) return;
    const context = this.minimap.getContext();
    for (const [tileX, tileY] of fresh) {
      context.fillStyle = cssColor(tileColor(tileX, tileY));
      context.fillRect(tileX, tileY, 1, 1);
    }
    this.minimap.refresh();
    this.report.dataset["fogRevealed"] = String(this.fog.revealedCount);
  }

  override update(): void {
    const now = performance.now();
    const own = this.view.renderPosition(this.view.selfId, now);
    if (own !== undefined) {
      const x = own.x * PIXELS_PER_SUB_UNIT;
      const y = own.y * PIXELS_PER_SUB_UNIT;
      const scroll = followScroll(x, y);
      this.cameras.main.setScroll(scroll.x, scroll.y);
      this.sight.setPosition(x, y);
      this.revealFog(x, y);
    }
    const camera = this.cameras.main;
    const minimapLeft = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
    this.minimapMarks.clear();

    const drawn: DrawnShip[] = [];
    const present = new Set<string>();
    for (const ship of this.view.ships()) {
      const position = this.view.renderPosition(ship.id, now);
      if (position === undefined) continue;
      present.add(ship.id);
      const mine = ship.id === this.view.selfId;
      let graphics = this.shipGraphics.get(ship.id);
      if (graphics === undefined) {
        graphics = this.drawShip(slotColor(ship.slot), mine);
        this.shipGraphics.set(ship.id, graphics);
      }
      const x = position.x * PIXELS_PER_SUB_UNIT;
      const y = position.y * PIXELS_PER_SUB_UNIT;
      graphics.setPosition(x, y);
      graphics.setRotation((ship.heading * 2 * Math.PI) / HEADING_COUNT);
      drawn.push({ id: ship.id, x: Math.round(x - camera.scrollX), y: Math.round(y - camera.scrollY), color: cssColor(slotColor(ship.slot)) });
      this.minimapMarks.fillStyle(mine ? OWN_RING_COLOR : slotColor(ship.slot), 1);
      this.minimapMarks.fillRect(minimapLeft + (x / TILE_PIXELS) * MINIMAP_SCALE - 1.5, MINIMAP_MARGIN + (y / TILE_PIXELS) * MINIMAP_SCALE - 1.5, 3, 3);
    }
    for (const [id, graphics] of this.shipGraphics) {
      if (present.has(id)) continue;
      graphics.destroy();
      this.shipGraphics.delete(id);
    }
    const report = JSON.stringify(drawn);
    if (report !== this.lastReport) {
      this.report.dataset["drawnShips"] = report;
      this.lastReport = report;
    }
    this.report.dataset["camera"] = `${camera.scrollX},${camera.scrollY}`;
  }

  /** A round hull with a bow pointing along +x; the player's own ship gets a pale ring. */
  private drawShip(color: number, own: boolean): Phaser.GameObjects.Graphics {
    const graphics = this.add.graphics();
    graphics.setDepth(2);
    graphics.fillStyle(color, 1);
    graphics.fillCircle(0, 0, 6);
    graphics.fillTriangle(3, -5, 12, 0, 3, 5);
    if (own) {
      graphics.lineStyle(2, OWN_RING_COLOR, 1);
      graphics.strokeCircle(0, 0, 10);
    }
    return graphics;
  }
}

export function startGame(parent: HTMLElement, view: MatchView): Phaser.Game {
  return new Phaser.Game({
    type: Phaser.AUTO,
    parent,
    width: VIEW_WIDTH,
    height: VIEW_HEIGHT,
    backgroundColor: SEA_COLOR,
    banner: false,
    audio: { noAudio: true },
    scene: new SeaScene(view, parent),
  });
}
import { expect, type APIRequestContext, type Page, type TestInfo } from "@playwright/test";
import { HEADING_COUNT, SUB_UNITS_PER_TILE } from "../../packages/content/src/index.js";
import { TEST_PLACEMENT_PATH } from "../../packages/protocol/src/index.js";

export const SERVER_URL = "http://localhost:2593";
export const TILE = SUB_UNITS_PER_TILE;
const PIXELS_PER_SUB_UNIT = 16 / SUB_UNITS_PER_TILE;

export interface Readout {
  readonly id: string;
  readonly slot: number;
  readonly x: number;
  readonly y: number;
  readonly heading: number;
  readonly speed: number;
  readonly dock: number;
}

export interface DrawnShip {
  readonly id: string;
  readonly x: number;
  readonly y: number;
  readonly color: string;
}

export async function createMatch(page: Page): Promise<string> {
  await page.goto("/");
  await page.getByRole("button", { name: "Create match" }).click();
  await expect(page.getByTestId("hud-status")).toHaveText("connected");
  const code = page.getByTestId("hud-code");
  await expect(code).toHaveText(/^[A-Z0-9]{6}$/);
  return (await code.textContent())!;
}

export async function joinMatch(page: Page, code: string): Promise<void> {
  await page.goto("/");
  await page.getByLabel("Match code").fill(code);
  await page.getByRole("button", { name: "Join" }).click();
  await expect(page.getByTestId("hud-status")).toHaveText("connected");
}

export async function selfId(page: Page): Promise<string> {
  return (await page.getByTestId("hud-self").textContent())!;
}

/** Every ship the page's HUD lists, with the latest decoded server state. */
export async function listed(page: Page): Promise<Readout[]> {
  return page.evaluate(() =>
    [...document.querySelectorAll<HTMLElement>('[data-testid="positions"] [data-ship-id]')].map((item) => ({
      id: item.dataset["shipId"]!,
      slot: Number(item.dataset["slot"]),
      x: Number(item.dataset["x"]),
      y: Number(item.dataset["y"]),
      heading: Number(item.dataset["heading"]),
      speed: Number(item.dataset["speed"]),
      dock: Number(item.dataset["dock"]),
    })),
  );
}

export async function listedIds(page: Page): Promise<string[]> {
  return (await listed(page)).map((ship) => ship.id).sort();
}

/** A ship's authoritative state in a page's HUD, or undefined when the page does not list it. */
export async function readout(page: Page, shipId: string): Promise<Readout | undefined> {
  return (await listed(page)).find((ship) => ship.id === shipId);
}

export async function drawnShips(page: Page): Promise<DrawnShip[]> {
  return JSON.parse((await page.getByTestId("game").getAttribute("data-drawn-ships")) ?? "[]") as DrawnShip[];
}

export async function drawnIds(page: Page): Promise<string[]> {
  return (await drawnShips(page)).map((ship) => ship.id).sort();
}

/**
 * Test-only placement (the server's PIRATE_SEA_RACE_TEST_PLACEMENT setting, on for these tests): puts a player's
 * ship at rest on a tile, then waits until the page shows it there.
 */
export async function place(request: APIRequestContext, page: Page, code: string, tileX: number, tileY: number, heading: number): Promise<void> {
  const sessionId = await selfId(page);
  const response = await request.post(`${SERVER_URL}${TEST_PLACEMENT_PATH}`, { data: { code, sessionId, tileX, tileY, heading } });
  expect(response.status(), await response.text()).toBe(200);
  await expect
    .poll(async () => {
      const ship = await readout(page, sessionId);
      return ship === undefined ? undefined : [ship.x, ship.y, ship.speed];
    })
    .toEqual([tileX * TILE + TILE / 2, tileY * TILE + TILE / 2, 0]);
}

/** Canvas pixels as RGBA rows, read from a real screenshot of the canvas. */
async function canvasPixels(page: Page, points: readonly { x: number; y: number }[], radius: number): Promise<[number, number, number][][]> {
  const png = await page.locator("#game canvas").screenshot();
  return page.evaluate(
    async ({ base64, points, radius }) => {
      const blob = await (await fetch(`data:image/png;base64,${base64}`)).blob();
      const bitmap = await createImageBitmap(blob);
      const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
      const context = canvas.getContext("2d")!;
      context.drawImage(bitmap, 0, 0);
      return points.map(({ x, y }) => {
        const pixels: [number, number, number][] = [];
        for (let dy = -radius; dy <= radius; dy++) {
          for (let dx = -radius; dx <= radius; dx++) {
            const px = x + dx;
            const py = y + dy;
            if (px < 0 || py < 0 || px >= bitmap.width || py >= bitmap.height) continue;
            const [r, g, b] = context.getImageData(px, py, 1, 1).data;
            pixels.push([r!, g!, b!]);
          }
        }
        return pixels;
      });
    },
    { base64: png.toString("base64"), points, radius },
  );
}

function near(pixel: [number, number, number], color: string, tolerance = 24): boolean {
  const want = Number.parseInt(color.slice(1), 16);
  const [r, g, b] = pixel;
  return Math.abs(r - ((want >> 16) & 0xff)) <= tolerance && Math.abs(g - ((want >> 8) & 0xff)) <= tolerance && Math.abs(b - (want & 0xff)) <= tolerance;
}

/**
 * The ids of ships whose colour is actually on the canvas where the scene says it drew them. Reads a real
 * screenshot of the canvas, so it checks rendered pixels rather than scene bookkeeping.
 */
export async function shipsOnCanvas(page: Page): Promise<string[]> {
  const drawn = await drawnShips(page);
  const pixels = await canvasPixels(page, drawn, 0);
  return drawn.filter((ship, index) => near(pixels[index]![0]!, ship.color)).map((ship) => ship.id).sort();
}

/** The camera's scroll, in world pixels. */
async function camera(page: Page): Promise<{ x: number; y: number }> {
  const [x, y] = ((await page.getByTestId("game").getAttribute("data-camera")) ?? "0,0").split(",").map(Number);
  return { x: x!, y: y! };
}

/**
 * Whether a ship's colour shows anywhere within a few pixels of where a ship at world position (x, y) sub-units would
 * be drawn on this page's canvas.
 */
export async function colourAt(page: Page, x: number, y: number, color: string): Promise<boolean> {
  const scroll = await camera(page);
  const point = { x: Math.round(x * PIXELS_PER_SUB_UNIT - scroll.x), y: Math.round(y * PIXELS_PER_SUB_UNIT - scroll.y) };
  const [pixels] = await canvasPixels(page, [point], 4);
  return pixels!.some((pixel) => near(pixel, color));
}

/** The colour a page draws its own ship in. */
export async function ownColour(page: Page): Promise<string> {
  const id = await selfId(page);
  await expect.poll(async () => (await drawnShips(page)).some((ship) => ship.id === id)).toBe(true);
  return (await drawnShips(page)).find((ship) => ship.id === id)!.color;
}

/** Holds the keys of a keyboard helm, sending only changes. */
class Keys {
  private readonly down = new Set<string>();

  constructor(private readonly page: Page) {}

  async set(key: string, pressed: boolean): Promise<void> {
    if (pressed === this.down.has(key)) return;
    if (pressed) {
      await this.page.keyboard.down(key);
      this.down.add(key);
    } else {
      await this.page.keyboard.up(key);
      this.down.delete(key);
    }
  }

  async releaseAll(): Promise<void> {
    for (const key of [...this.down]) await this.set(key, false);
  }
}

export interface SailOptions {
  /** Stop once the ship is this close to the target, in sub-units. */
  readonly within?: number;
  /** Or once this holds. */
  readonly until?: () => Promise<boolean>;
  readonly timeoutMs?: number;
  /** Called with every readout on the way, for checks along the route. */
  readonly onReadout?: (ship: Readout) => void;
}

/**
 * Sails a page's ship toward a world position with the keyboard only, steering from the HUD's authoritative readout:
 * left or right toward the bearing, up when roughly on course and below the wanted speed, down when too fast. The
 * wanted speed falls as the target nears, so the ship arrives slowly.
 */
export async function sailTo(page: Page, target: { x: number; y: number }, options: SailOptions = {}): Promise<Readout> {
  const id = await selfId(page);
  const keys = new Keys(page);
  const deadline = Date.now() + (options.timeoutMs ?? 30_000);
  try {
    for (;;) {
      const ship = await readout(page, id);
      if (ship === undefined) throw new Error("own ship missing from the HUD");
      options.onReadout?.(ship);
      const dx = target.x - ship.x;
      const dy = target.y - ship.y;
      const distance = Math.hypot(dx, dy);
      if (options.within !== undefined && distance <= options.within) return ship;
      if (options.until !== undefined && (await options.until())) return ship;
      if (Date.now() > deadline) throw new Error(`did not reach ${target.x},${target.y} (at ${ship.x},${ship.y})`);
      const bearing = Math.round((Math.atan2(dy, dx) / (2 * Math.PI)) * HEADING_COUNT);
      const turn = ((((bearing - ship.heading) % HEADING_COUNT) + HEADING_COUNT + HEADING_COUNT / 2) % HEADING_COUNT) - HEADING_COUNT / 2;
      await keys.set("ArrowRight", turn > 0);
      await keys.set("ArrowLeft", turn < 0);
      const wanted = Math.min(64, Math.max(14, (distance / TILE) * 10));
      const onCourse = Math.abs(turn) <= 4;
      await keys.set("ArrowUp", onCourse && ship.speed < wanted - 2);
      await keys.set("ArrowDown", ship.speed > wanted + 8);
      await page.waitForTimeout(30);
    }
  } finally {
    await keys.releaseAll();
  }
}

/** Attaches the one screenshot a scenario's verifier reads. */
export async function attachScreenshot(page: Page, testInfo: TestInfo, scenario: string): Promise<void> {
  const path = testInfo.outputPath(`${scenario}.png`);
  await page.screenshot({ path });
  await testInfo.attach(`screenshot:${scenario}`, { path, contentType: "image/png" });
}

