import { seaMap, terrainAt, Terrain } from "../packages/content/src/index.js";
const S = [51, 60], route = [[51, 60], [58, 57], [58, 52], [51, 50]];
const seg = (p: number[], a: number[], b: number[]) => { const dx = b[0]! - a[0]!, dy = b[1]! - a[1]!; const t = Math.max(0, Math.min(1, ((p[0]! - a[0]!) * dx + (p[1]! - a[1]!) * dy) / (dx * dx + dy * dy))); return Math.hypot(p[0]! - a[0]! - t * dx, p[1]! - a[1]! - t * dy); };
const out = [];
for (let y = 30; y < 70; y++) for (let x = 35; x < 75; x++) {
  let sea = true; for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) if (terrainAt(seaMap, x + dx, y + dy) !== Terrain.Sea) sea = false;
  if (!sea) continue;
  const fromStart = Math.hypot(x - S[0]!, y - S[1]!);
  const spawn = Math.min(...seaMap.spawnSlots.map((s) => seg([x, y], [s.tileX, s.tileY], S)));
  let r = Infinity; for (let i = 0; i < 3; i++) r = Math.min(r, seg([x, y], route[i]!, route[i + 1]!));
  const berth = Math.hypot(x - 51, y - 50);
  if (fromStart > 12 && spawn > 12.5 && r <= 7 && berth >= 5) out.push([x, y, fromStart.toFixed(1), spawn.toFixed(1), r.toFixed(1), berth.toFixed(1)].join(" "));
}
console.log(out.join("\n"));
EOF
